create table if not exists public.alchemy_entitlements(user_id uuid primary key references auth.users(id) on delete cascade,plan text not null default 'trial',status text not null default 'trialing',trial_limit integer not null default 10,trial_used integer not null default 0,period_limit integer,period_used integer not null default 0,period_ends_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.alchemy_experiments(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,title text not null default 'Untitled experiment',input jsonb not null default '{}'::jsonb,output jsonb not null default '{}'::jsonb,provider text not null default 'rules',model text,recipe_id uuid references public.recipes(id) on delete set null,created_at timestamptz not null default now());
alter table public.alchemy_entitlements enable row level security;alter table public.alchemy_experiments enable row level security;
create policy alchemy_entitlements_select_own on public.alchemy_entitlements for select to authenticated using(user_id=auth.uid());
create policy alchemy_experiments_select_own on public.alchemy_experiments for select to authenticated using(owner_id=auth.uid());create policy alchemy_experiments_insert_own on public.alchemy_experiments for insert to authenticated with check(owner_id=auth.uid());create policy alchemy_experiments_delete_own on public.alchemy_experiments for delete to authenticated using(owner_id=auth.uid());
create or replace function public.consume_alchemy_credit()returns table(allowed boolean,remaining integer,plan text,status text)language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();r public.alchemy_entitlements%rowtype;begin if u is null then raise exception 'authentication required';end if;insert into public.alchemy_entitlements(user_id)values(u)on conflict(user_id)do nothing;select * into r from public.alchemy_entitlements where user_id=u for update;if r.status='active' and r.plan in('pro','studio','admin')and(r.period_limit is null or r.period_used<r.period_limit)then update public.alchemy_entitlements set period_used=period_used+1,updated_at=now()where user_id=u;return query select true,case when r.period_limit is null then -1 else greatest(0,r.period_limit-r.period_used-1)end,r.plan,r.status;return;end if;if r.status='trialing' and r.trial_used<r.trial_limit then update public.alchemy_entitlements set trial_used=trial_used+1,updated_at=now()where user_id=u;return query select true,greatest(0,r.trial_limit-r.trial_used-1),r.plan,r.status;return;end if;return query select false,0,r.plan,r.status;end;$$;
revoke all on function public.consume_alchemy_credit() from public;grant execute on function public.consume_alchemy_credit() to authenticated;
